// Analisis de anomalias.
//
// Es deterministico y no usa un modelo de lenguaje, a proposito. Un
// informe automatico que se archiva y se usa como evidencia tiene que dar
// el mismo resultado con los mismos datos; un modelo no garantiza eso, y
// ademas significaria mandar las metricas del proyecto a un servicio de
// un tercero sin necesidad. Los umbrales de abajo son los mismos de las
// reglas de alerta del punto 10, con su justificacion.
//
// Si alguna consulta a Prometheus fallo, se dice en el informe en vez de
// inventar un numero o dejar el renglon en blanco.

const leer = (nodo) => {
  const r = $(nodo).first().json;
  if (r?.status !== 'success' || !Array.isArray(r?.data?.result)) return null;
  return r.data.result;
};

const estado = leer('Estado actual');
const p95 = leer('Percentil 95 por ruta');
const trafico = leer('Peticiones y errores');

const valor = (serie) => Number(serie?.value?.[1]);
const UMBRAL_P95_SEG = 1.0;          // la regla de latencia del punto 10
const UMBRAL_ERRORES_PCT = 5;        // 5% de 5xx sobre el total
const UMBRAL_MEMORIA_PCT = 80;       // contra el techo real de V8, no contra el reservado

const hallazgos = [];
const faltantes = [];

// --- disponibilidad ------------------------------------------------------
let lineasEstado = [];
if (!estado) {
  faltantes.push('estado de los servicios');
} else {
  for (const s of estado.filter((x) => x.metric.__name__ === 'up')) {
    const vivo = valor(s) === 1;
    lineasEstado.push(`| ${s.metric.job || '?'} | ${s.metric.instance || '?'} | ${vivo ? 'arriba' : '**CAIDO**'} |`);
    if (!vivo) hallazgos.push(`El destino **${s.metric.job}/${s.metric.instance}** figura caido ahora mismo.`);
  }

  const replica = estado.find((x) => x.metric.__name__ === 'pg_replication_is_replica' && valor(x) === 1);
  if (!replica) {
    hallazgos.push('Ningun nodo de PostgreSQL se declara replica. O la replica no esta levantada, o su exportador no responde: **no hay copia en caliente**.');
  }

  const usado = estado.find((x) => x.metric.__name__ === 'nodejs_heap_size_used_bytes');
  const techo = estado.find((x) => x.metric.__name__ === 'nodejs_heap_size_limit_bytes');
  if (usado && techo && valor(techo) > 0) {
    const pct = (valor(usado) / valor(techo)) * 100;
    lineasEstado.push(`| backend | monticulo de V8 | ${pct.toFixed(1)}% del techo (${(valor(techo) / 1048576).toFixed(0)} MB) |`);
    if (pct > UMBRAL_MEMORIA_PCT) {
      hallazgos.push(`El monticulo del backend esta al **${pct.toFixed(1)}%** de su techo. A los 100% el proceso muere: es lo que paso en el punto 5.`);
    }
  }
}

// --- latencia ------------------------------------------------------------
let lineasLatencia = [];
if (!p95) {
  faltantes.push('percentil 95 de latencia');
} else if (p95.length === 0) {
  faltantes.push('percentil 95 de latencia (no hay datos: el backend no recibio trafico en la semana)');
} else {
  const ordenadas = p95.filter((s) => Number.isFinite(valor(s)))
    .sort((a, b) => valor(b) - valor(a)).slice(0, 10);
  for (const s of ordenadas) {
    const seg = valor(s);
    lineasLatencia.push(`| \`${s.metric.route || 'desconocida'}\` | ${(seg * 1000).toFixed(1)} ms |`);
    if (seg > UMBRAL_P95_SEG) {
      hallazgos.push(`La ruta \`${s.metric.route}\` tarda **${(seg * 1000).toFixed(0)} ms** en el percentil 95 (umbral: ${UMBRAL_P95_SEG * 1000} ms).`);
    }
  }
}

// --- errores -------------------------------------------------------------
let lineasTrafico = [];
let totalPeticiones = 0;
let totalErrores = 0;
if (!trafico) {
  faltantes.push('conteo de peticiones y errores');
} else {
  const porRuta = {};
  for (const s of trafico) {
    const n = valor(s);
    if (!Number.isFinite(n)) continue;
    const ruta = s.metric.route || 'desconocida';
    const codigo = String(s.metric.status_code || '');
    porRuta[ruta] = porRuta[ruta] || { total: 0, errores: 0 };
    porRuta[ruta].total += n;
    totalPeticiones += n;
    if (codigo.startsWith('5')) { porRuta[ruta].errores += n; totalErrores += n; }
  }
  for (const [ruta, d] of Object.entries(porRuta).sort((a, b) => b[1].total - a[1].total).slice(0, 10)) {
    const pct = d.total > 0 ? (d.errores / d.total) * 100 : 0;
    lineasTrafico.push(`| \`${ruta}\` | ${Math.round(d.total)} | ${Math.round(d.errores)} | ${pct.toFixed(1)}% |`);
    if (pct > UMBRAL_ERRORES_PCT && d.total >= 20) {
      hallazgos.push(`La ruta \`${ruta}\` devolvio **${pct.toFixed(1)}% de errores 5xx** sobre ${Math.round(d.total)} peticiones.`);
    }
  }
}

// --- armado del informe --------------------------------------------------
const hoy = new Date();
const fecha = hoy.toISOString().slice(0, 10);
const nada = (a) => (a.length ? a.join('\n') : '| (sin datos) | | |');

const md = `# Informe semanal de rendimiento — RestoYa

**Generado:** ${hoy.toISOString()}  
**Periodo:** los 7 dias anteriores  
**Origen:** Prometheus (http://prometheus:9090)  
**Generado por:** flujo F03 de n8n, sin intervencion manual.

---

## Resumen

${hallazgos.length === 0
  ? 'Sin anomalias por encima de los umbrales definidos en el punto 10.'
  : `**${hallazgos.length} hallazgo(s):**\n\n` + hallazgos.map((h) => `- ${h}`).join('\n')}
${faltantes.length ? `\n> **Datos que no se pudieron leer:** ${faltantes.join('; ')}. Los numeros de abajo que dependan de eso estan incompletos.` : ''}

---

## Estado de los servicios

| Servicio | Instancia | Estado |
|---|---|---|
${nada(lineasEstado)}

## Latencia (percentil 95, 7 dias)

Diez rutas mas lentas. Umbral: ${UMBRAL_P95_SEG * 1000} ms.

| Ruta | p95 |
|---|---|
${lineasLatencia.length ? lineasLatencia.join('\n') : '| (sin trafico en el periodo) | |'}

## Trafico y errores (7 dias)

Total: ${Math.round(totalPeticiones)} peticiones, ${Math.round(totalErrores)} con error 5xx (${totalPeticiones > 0 ? ((totalErrores / totalPeticiones) * 100).toFixed(2) : '0.00'}%).

| Ruta | Peticiones | Errores 5xx | % |
|---|---|---|---|
${lineasTrafico.length ? lineasTrafico.join('\n') : '| (sin trafico en el periodo) | | | |'}

---

## Como se analiza

El analisis es deterministico y **no usa un modelo de lenguaje**. Es una
decision, no una limitacion: este informe se archiva y se usa como
evidencia, asi que con los mismos datos tiene que dar el mismo resultado.
Un modelo no garantiza eso, y ademas obligaria a mandar las metricas del
proyecto a un servicio de un tercero sin necesidad.

Los umbrales son los mismos de las reglas de alerta del punto 10:

| Que | Umbral | Por que |
|---|---|---|
| Latencia p95 | ${UMBRAL_P95_SEG * 1000} ms | Despues del punto 5 ninguna consulta pasa de 1,4 ms; un segundo de p95 es espera, no base de datos |
| Errores 5xx | ${UMBRAL_ERRORES_PCT}% | Por debajo son fallos sueltos; por encima es algo roto |
| Monticulo de V8 | ${UMBRAL_MEMORIA_PCT}% del **techo** | Medido contra heap_size_limit y no contra el reservado: ese error nos tuvo una alerta sonando sin motivo (INC-13) |
`;

return [{ json: {
  nombreArchivo: `informe-rendimiento-${fecha}.md`,
  contenido: md,
  hallazgos: hallazgos.length,
  faltantes: faltantes.length,
} }];
